document.addEventListener('DOMContentLoaded',function (){const forms=document.querySelectorAll('form');forms.forEach(form=>{form.addEventListener('submit',function (e){const editors=form.querySelectorAll('.pro-editor-mount');console.log(`[Form Sync] Found ${editors.length}editors on form`);editors.forEach((editorMount,index)=>{const hiddenTextarea=editorMount.querySelector('textarea[style*="display:none"]');if (hiddenTextarea){const editorArea=editorMount.querySelector('.pro-editor-content');if (editorArea){const content=editorArea.innerHTML;hiddenTextarea.value=content;const fieldName=hiddenTextarea.getAttribute('data-name')||editorMount.getAttribute('data-field-name');console.log(`[Form Sync] Editor ${index}:field="${fieldName}",content_length=${content.length}`);if (!hiddenTextarea.name){hiddenTextarea.name=fieldName;console.log(`[Form Sync] Set name attribute to:${fieldName}`);}}else{console.warn(`[Form Sync] No editor area found for editor ${index}`);}}else{console.warn(`[Form Sync] No hidden textarea found for editor ${index}`);}});});});document.addEventListener('blur',function (e){if (e.target&&e.target.classList&&e.target.classList.contains('pro-editor-content')){const editorMount=e.target.closest('.pro-editor-mount');if (editorMount){const hiddenTextarea=editorMount.querySelector('textarea[style*="display:none"]');if (hiddenTextarea){hiddenTextarea.value=e.target.innerHTML;console.log(`[Form Sync] Synced on blur:${hiddenTextarea.name}`);}}}},true);setInterval(function (){const editors=document.querySelectorAll('.pro-editor-mount');editors.forEach(editorMount=>{const hiddenTextarea=editorMount.querySelector('textarea[style*="display:none"]');const editorArea=editorMount.querySelector('.pro-editor-content');if (hiddenTextarea&&editorArea){hiddenTextarea.value=editorArea.innerHTML;}});},5000);});